<?php
declare(strict_types=1);require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_once __DIR__.'/../includes/permisos.php';require_once __DIR__.'/../models/MgSeguimientoModel.php';require_role(['administrador','coordinador_mg','auxiliar_mg']);requerir_permiso('mg.dashboard.ver');$m=new MgSeguimientoModel($pdo);$alertas=$m->alertas();$abiertas=array_values(array_filter($alertas,fn($a)=>!$m->atendida($a['tipo'],$a['id'])));$k=[];$k['activos']=(int)$pdo->query("SELECT COUNT(*) FROM expedientes_mg WHERE estado='activo'")->fetchColumn();$k['mg1']=(int)$pdo->query("SELECT COUNT(*) FROM expedientes_mg WHERE estado='activo' AND etapa_actual='mg1'")->fetchColumn();$k['mg2']=(int)$pdo->query("SELECT COUNT(*) FROM expedientes_mg WHERE estado='activo' AND etapa_actual='mg2'")->fetchColumn();$k['defensas14']=(int)$pdo->query("SELECT COUNT(*) FROM defensas_mg WHERE estado='programada' AND fecha BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 14 DAY)")->fetchColumn();$k['alertas_altas']=count(array_filter($abiertas,fn($a)=>$a['severidad']==='alta'));$k['cartas_mes']=(int)$pdo->query("SELECT COUNT(*) FROM documentos_generados WHERE tipo='CARTA_ASIGNACION_TUTOR' AND YEAR(fecha_generacion)=YEAR(CURDATE()) AND MONTH(fecha_generacion)=MONTH(CURDATE())")->fetchColumn();$carga=$pdo->query('SELECT CONCAT(u.nombre," ",u.apellido) tutor,COUNT(a.id_asignacion) carga FROM tutores t JOIN profesores p ON p.id_profesor=t.id_profesor JOIN usuarios u ON u.id_usuario=p.id_usuario LEFT JOIN asignaciones_tutor a ON a.id_tutor=t.id_tutor AND a.estado="vigente" GROUP BY t.id_tutor,u.nombre,u.apellido ORDER BY carga DESC,u.apellido')->fetchAll();$tituloPagina='Dashboard Coordinador MG';require __DIR__.'/../views/mg/dashboard.php';
